// Kettle: the game this course's toolkit plays. Do not edit this file; the checks hash it.
//
// One frame is one call of step(state, input). The whole game state is 32 bytes of RAM, like a small console.
// step changes that RAM in place and returns the same state object.
//
// Units: positions in sub-pixels (1/16 of a pixel), speeds in sub-pixels per frame. Tiles are 8 pixels.

export const SUB = 16;
export const TILE = 8 * SUB;
export const W = 6 * SUB;   // Kettle is 6 pixels wide
export const H = 8 * SUB;   // and 8 tall: one tile, so a sample at the head and one at the feet cover every row

// Buttons, as bits of one input number per frame.
export const L = 1, R = 2, J = 4;
// The six inputs worth pressing: nothing, left, right, jump, left+jump, right+jump.
export const INPUTS = [0, L, R, J, L | J, R | J];

// The RAM map: the address of every value the game keeps.
export const RAM_SIZE = 32;
export const ADDR = {
  FRAME: 0x00, // u16: frames played
  X: 0x02,     // u16: left edge, sub-pixels
  Y: 0x04,     // u16: top edge, sub-pixels
  VX: 0x06,    // s16: horizontal speed
  VY: 0x08,    // s16: vertical speed, down is positive
  FLAGS: 0x0a, // bit 0: standing on ground; bit 1: jump was held last frame
  RNG: 0x0b,   // u16: the random generator's state
  COUNT: 0x0d, // gems held
  SLOTS: 0x0e, // four item slots, 0x0e to 0x11
  DONE: 0x12,  // non-zero once the level is complete
  DEAD: 0x13,  // 1 once Kettle has touched spikes or fallen out
  DROP: 0x14,  // which of the level's drop places the bell chose; 255 before it rings
  BELL: 0x15,  // 1 once the bell has rung
  TAKEN: 0x16, // bit i set once gem i is collected
};
export const GROUND = 1, HELD = 2;

// How Kettle moves, in sub-pixels.
const WALK_MAX = 24;   // 1.5 px a frame
const ACCEL = 8;       // on the ground
const FRICTION = 8;    // on the ground with no direction held
const AIR_ACCEL = 8;   // in the air, up to WALK_MAX
const BELT = 8;        // a belt adds this on top of Kettle's own speed
const RUN = 32;        // a jump made faster than this...
const BOOST = 8;       // ...gets this extra push
const JUMP = 72;       // speed of a jump
const CUT = 16;        // letting go of jump while rising caps the rise speed here
const GRAVITY = 8;
const FALL_MAX = 64;
const VX_CAP = 96;

export const VERSIONS = ['1.0', '1.1'];

const u16 = (ram, a) => ram[a] | (ram[a + 1] << 8);
const s16 = (ram, a) => { const v = u16(ram, a); return v & 0x8000 ? v - 0x10000 : v; };
const put16 = (ram, a, v) => { ram[a] = v & 255; ram[a + 1] = (v >> 8) & 255; };

// A level from its text: header lines "key: value", a line "---", then one row of tiles per line.
// Tiles: # stone, > and < belts (solid, they carry whatever stands on them), B bell (solid), ^ spikes,
// F flag, g gem, S start, . air.
export function parseLevel(text) {
  const [head, body] = text.replace(/\r/g, '').split('\n---\n');
  if (body === undefined) throw new Error('a level needs a "---" line between its header and its rows');
  const info = Object.fromEntries(head.split('\n').filter((l) => l.trim()).map((l) => {
    const at = l.indexOf(':');
    return [l.slice(0, at).trim(), l.slice(at + 1).trim()];
  }));
  const rows = body.split('\n').map((r) => r.trim()).filter(Boolean);
  const w = rows[0].length;
  if (rows.some((r) => r.length !== w)) throw new Error('every row of a level must be the same length');
  let start = null;
  const gems = [];
  const tiles = rows.map((r, ty) => [...r].map((c, tx) => {
    if (c === 'S') { start = { tx, ty }; return '.'; }
    if (c === 'g') { gems.push({ tx, ty }); return '.'; }
    return c;
  }));
  if (!start) throw new Error('a level needs a start tile S');
  const drop = info.drop ? info.drop.split(/\s+/) : null; // "block ROW COL,COL,COL,COL" or "gem ROW COL,..."
  const level = {
    name: info.name ?? 'untitled',
    par: info.par ? Number(info.par) : null,
    seed: info.seed ? Number(info.seed) : 1,
    w, h: rows.length, tiles, start, gems,
    dropKind: drop ? drop[0] : null,
    dropRow: drop ? Number(drop[1]) : -1,
    dropCols: drop ? drop[2].split(',').map(Number) : [],
  };
  return deepFreeze(level);
}
function deepFreeze(o) {
  Object.values(o).forEach((v) => { if (v && typeof v === 'object') deepFreeze(v); });
  return Object.freeze(o);
}

export function newState(level, version = '1.0') {
  if (!VERSIONS.includes(version)) throw new Error(`unknown game version ${version}; there are ${VERSIONS.join(' and ')}`);
  const ram = new Uint8Array(RAM_SIZE);
  put16(ram, ADDR.X, level.start.tx * TILE + (TILE - W) / 2);
  put16(ram, ADDR.Y, (level.start.ty + 1) * TILE - H);
  put16(ram, ADDR.RNG, level.seed);
  ram[ADDR.FLAGS] = GROUND;
  ram[ADDR.DROP] = 255;
  return { ram, level, version };
}

// A 16-bit xorshift generator. It advances once every frame and once more on every jump.
function nextRandom(ram) {
  let x = u16(ram, ADDR.RNG);
  x ^= (x << 7) & 0xffff;
  x ^= x >> 9;
  x ^= (x << 8) & 0xffff;
  put16(ram, ADDR.RNG, x);
  return x;
}

const dropActive = (st, kind) => st.level.dropKind === kind && st.ram[ADDR.DROP] !== 255;

// The tile under a point given in sub-pixels. Outside the level's sides and above it is stone.
export function tileAt(st, px, py) {
  const tx = Math.floor(px / TILE), ty = Math.floor(py / TILE);
  const lv = st.level;
  if (tx < 0 || tx >= lv.w || ty < 0) return '#';
  if (ty >= lv.h) return '.';
  if (dropActive(st, 'block') && tx === lv.dropCols[st.ram[ADDR.DROP]] && ty === lv.dropRow) return '#';
  return lv.tiles[ty][tx];
}
const solid = (c) => c === '#' || c === 'B' || c === '>' || c === '<';

function moveX(st, vx) {
  const ram = st.ram;
  let x = u16(ram, ADDR.X) + vx;
  const y = u16(ram, ADDR.Y);
  if (vx !== 0) {
    // Only the edge Kettle moves toward is tested, at the head and at the feet.
    const edge = vx > 0 ? x + W - 1 : x;
    if (solid(tileAt(st, edge, y)) || solid(tileAt(st, edge, y + H - 1))) {
      const col = Math.floor(edge / TILE);
      const depth = vx > 0 ? edge - col * TILE + 1 : (col + 1) * TILE - edge;
      // Push Kettle out of the tile on the nearer side.
      const farSide = depth > TILE / 2;
      if (vx > 0) x = farSide ? (col + 1) * TILE : col * TILE - W;
      else x = farSide ? col * TILE - W : (col + 1) * TILE;
      if (!farSide) put16(ram, ADDR.VX, 0);
    }
  }
  put16(ram, ADDR.X, x);
}

function moveY(st, vy) {
  const ram = st.ram;
  const x = u16(ram, ADDR.X);
  let y = u16(ram, ADDR.Y) + vy;
  ram[ADDR.FLAGS] &= ~GROUND;
  if (vy > 0) {
    const foot = y + H - 1;
    if (solid(tileAt(st, x, foot)) || solid(tileAt(st, x + W - 1, foot))) {
      y = Math.floor(foot / TILE) * TILE - H;
      put16(ram, ADDR.VY, 0);
      ram[ADDR.FLAGS] |= GROUND;
    }
  } else if (vy < 0) {
    if (solid(tileAt(st, x, y)) || solid(tileAt(st, x + W - 1, y))) {
      if (tileAt(st, x + W / 2, y) === 'B' && !ram[ADDR.BELL]) ringBell(st);
      y = (Math.floor(y / TILE) + 1) * TILE;
      put16(ram, ADDR.VY, 0);
    }
  }
  put16(ram, ADDR.Y, y);
}

function ringBell(st) {
  const ram = st.ram;
  ram[ADDR.BELL] = 1;
  const n = st.level.dropCols.length;
  if (n) ram[ADDR.DROP] = nextRandom(ram) % n;
}

function overlaps(x, y, tx, ty) {
  const gx = tx * TILE, gy = ty * TILE;
  return !(x + W <= gx || x >= gx + TILE || y + H <= gy || y >= gy + TILE);
}

function touch(st) {
  const ram = st.ram, x = u16(ram, ADDR.X), y = u16(ram, ADDR.Y);
  for (const [px, py] of [[x, y], [x + W - 1, y], [x, y + H - 1], [x + W - 1, y + H - 1]]) {
    const c = tileAt(st, px, py);
    if (c === '^') ram[ADDR.DEAD] = 1;
    if (c === 'F') ram[ADDR.DONE] = 1;
  }
  const gems = st.level.gems.slice();
  if (dropActive(st, 'gem')) gems.push({ tx: st.level.dropCols[ram[ADDR.DROP]], ty: st.level.dropRow });
  // Whether there is room is decided once, before looking at the gems Kettle touches this frame.
  const room = ram[ADDR.COUNT] < 4;
  gems.forEach((g, i) => {
    if (!room || (ram[ADDR.TAKEN] & (1 << i)) || !overlaps(x, y, g.tx, g.ty)) return;
    ram[ADDR.TAKEN] |= 1 << i;
    ram[ADDR.SLOTS + ram[ADDR.COUNT]] = i + 1;
    ram[ADDR.COUNT] += 1;
  });
}

export function step(st, input) {
  const ram = st.ram;
  if (ram[ADDR.DONE] || ram[ADDR.DEAD]) return st;
  const dir = ((input & R) ? 1 : 0) - ((input & L) ? 1 : 0);
  const jump = (input & J) !== 0;
  let vx = s16(ram, ADDR.VX), vy = s16(ram, ADDR.VY);
  const ground = (ram[ADDR.FLAGS] & GROUND) !== 0;
  const held = (ram[ADDR.FLAGS] & HELD) !== 0;

  nextRandom(ram);
  if (ground && jump && !held) {
    vy = -JUMP;
    if (Math.abs(vx) >= RUN && Math.sign(vx) === dir) vx += dir * BOOST;
    nextRandom(ram);
  } else if (ground) {
    if (Math.abs(vx) > WALK_MAX) vx = Math.sign(vx) * WALK_MAX;
    if (dir !== 0) {
      vx += dir * ACCEL;
      if (Math.abs(vx) > WALK_MAX) vx = Math.sign(vx) * WALK_MAX;
    } else {
      vx = Math.abs(vx) <= FRICTION ? 0 : vx - Math.sign(vx) * FRICTION;
    }
    const under = tileAt(st, u16(ram, ADDR.X) + W / 2, u16(ram, ADDR.Y) + H);
    if (under === '>') vx += BELT;
    if (under === '<') vx -= BELT;
  } else if (dir !== 0 && dir * vx < WALK_MAX) {
    vx = dir * Math.min(dir * vx + AIR_ACCEL, WALK_MAX);
  }
  if (!jump && vy < -CUT) vy = -CUT;
  vy = Math.min(vy + GRAVITY, FALL_MAX);
  vx = Math.max(-VX_CAP, Math.min(VX_CAP, vx));
  put16(ram, ADDR.VX, vx);
  put16(ram, ADDR.VY, vy);
  ram[ADDR.FLAGS] = (ram[ADDR.FLAGS] & ~HELD) | (jump ? HELD : 0);
  if (st.version === '1.1') { moveY(st, vy); moveX(st, vx); } // 1.1 settles the vertical move first
  else { moveX(st, vx); moveY(st, vy); }
  touch(st);
  put16(ram, ADDR.FRAME, u16(ram, ADDR.FRAME) + 1);
  if (u16(ram, ADDR.Y) > st.level.h * TILE) ram[ADDR.DEAD] = 1;
  return st;
}

// The game's sync check: FNV-1a over the 32 bytes of RAM.
export function hash(st) {
  let h = 0x811c9dc5;
  for (const b of st.ram) { h ^= b; h = Math.imul(h, 0x01000193) >>> 0; }
  return h;
}
